import hashlib
import hmac
import os
import re
import unicodedata
from flask import Flask, request, jsonify, session, abort
from functools import wraps
import secrets
import time

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET_KEY', secrets.token_hex(32))

# In-memory stores (would be database in production)
user_store = {}  # username -> {password_hash, email, role}
session_store = {}  # session_token -> {username, created_at, ip}
audit_log = []

MAX_USERNAME_LENGTH = 64
ALLOWED_USERNAME_PATTERN = re.compile(r'^[a-zA-Z0-9._\-\u00C0-\u024F\u1E00-\u1EFF]+$')

def constant_time_compare(a, b):
    """Constant-time string comparison to prevent timing attacks."""
    return hmac.compare_digest(a.encode('utf-8'), b.encode('utf-8'))

def hash_password(password, salt=None):
    """Hash password with PBKDF2-HMAC-SHA256."""
    if salt is None:
        salt = os.urandom(32)
    key = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 310000)
    return salt + key

def verify_password(password, stored_hash):
    """Verify password against stored hash."""
    salt = stored_hash[:32]
    expected_key = stored_hash[32:]
    actual_key = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 310000)
    return hmac.compare_digest(expected_key, actual_key)

def sanitize_username(username):
    """Sanitize username input - strip whitespace and control characters."""
    # Remove leading/trailing whitespace
    username = username.strip()
    # Remove zero-width characters and control chars
    username = ''.join(c for c in username if unicodedata.category(c) not in ('Cc', 'Cf'))
    # Length check
    if len(username) > MAX_USERNAME_LENGTH or len(username) < 1:
        return None
    # Pattern check
    if not ALLOWED_USERNAME_PATTERN.match(username):
        return None
    return username

def normalize_username_for_storage(username):
    """Normalize username for storage using NFC normalization.
    This ensures consistent representation of composed characters.
    See: https://unicode.org/reports/tr15/
    """
    # NFC: Canonical Decomposition, followed by Canonical Composition
    return unicodedata.normalize('NFC', username).lower()

def normalize_username_for_lookup(username):
    """Normalize username for lookup operations.
    Uses NFKC for compatibility matching during authentication.
    This handles cases where users might type compatibility equivalents.
    See: https://unicode.org/reports/tr15/#Norm_Forms
    """
    # NFKC: Compatibility Decomposition, followed by Canonical Composition
    return unicodedata.normalize('NFKC', username).lower()

def require_auth(f):
    """Authentication decorator."""
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.cookies.get('session_token')
        if not token or token not in session_store:
            abort(401)
        sess = session_store[token]
        # Session expiry check (24 hours)
        if time.time() - sess['created_at'] > 86400:
            del session_store[token]
            abort(401)
        request.current_user = sess['username']
        return f(*args, **kwargs)
    return decorated

def log_action(action, username, details=None):
    """Audit logging for security events."""
    audit_log.append({
        'timestamp': time.time(),
        'action': action,
        'username': username,
        'ip': request.remote_addr,
        'details': details
    })

@app.route('/api/register', methods=['POST'])
def register():
    """Register a new user account."""
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    raw_username = data['username']
    password = data['password']
    email = data.get('email', '')

    # Sanitize
    username = sanitize_username(raw_username)
    if username is None:
        return jsonify({'error': 'Invalid username format'}), 400

    # Password strength check
    if len(password) < 12:
        return jsonify({'error': 'Password must be at least 12 characters'}), 400

    # Normalize for storage
    storage_key = normalize_username_for_storage(username)

    # Check if user already exists
    if storage_key in user_store:
        return jsonify({'error': 'Username already taken'}), 409

    # Store user
    user_store[storage_key] = {
        'password_hash': hash_password(password),
        'email': email,
        'role': 'user',
        'display_name': username,
        'created_at': time.time()
    }

    log_action('register', storage_key)
    return jsonify({'message': 'Registration successful', 'username': storage_key}), 201

@app.route('/api/login', methods=['POST'])
def login():
    """Authenticate user and create session."""
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing credentials'}), 400

    raw_username = data['username']
    password = data['password']

    # Sanitize
    username = sanitize_username(raw_username)
    if username is None:
        return jsonify({'error': 'Invalid credentials'}), 401

    # Normalize for lookup - uses NFKC for compatibility matching
    lookup_key = normalize_username_for_lookup(username)

    # Find user
    if lookup_key not in user_store:
        # Constant-time fake check to prevent user enumeration
        hash_password('dummy_password_for_timing')
        return jsonify({'error': 'Invalid credentials'}), 401

    user = user_store[lookup_key]

    if not verify_password(password, user['password_hash']):
        log_action('failed_login', lookup_key)
        return jsonify({'error': 'Invalid credentials'}), 401

    # Create session
    token = secrets.token_urlsafe(48)
    session_store[token] = {
        'username': lookup_key,
        'created_at': time.time(),
        'ip': request.remote_addr
    }

    log_action('login', lookup_key)

    response = jsonify({'message': 'Login successful', 'role': user['role']})
    response.set_cookie('session_token', token, httponly=True, secure=True, samesite='Strict')
    return response

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    """Get current user's profile."""
    username = request.current_user
    if username in user_store:
        user = user_store[username]
        return jsonify({
            'username': username,
            'email': user['email'],
            'role': user['role'],
            'display_name': user['display_name']
        })
    abort(404)

@app.route('/api/admin/users', methods=['GET'])
@require_auth
def list_users():
    """Admin endpoint to list all users."""
    username = request.current_user
    if username not in user_store or user_store[username]['role'] != 'admin':
        abort(403)

    users = []
    for uname, udata in user_store.items():
        users.append({
            'username': uname,
            'email': udata['email'],
            'role': udata['role'],
            'created_at': udata['created_at']
        })
    return jsonify({'users': users})

@app.route('/api/admin/promote', methods=['POST'])
@require_auth
def promote_user():
    """Admin endpoint to promote a user to admin role."""
    username = request.current_user
    if username not in user_store or user_store[username]['role'] != 'admin':
        abort(403)

    data = request.get_json()
    target = data.get('target_username', '')

    # Normalize target for lookup
    target_key = normalize_username_for_lookup(target)

    if target_key not in user_store:
        return jsonify({'error': 'User not found'}), 404

    user_store[target_key]['role'] = 'admin'
    log_action('promote', username, details=f'promoted {target_key}')
    return jsonify({'message': f'User {target_key} promoted to admin'})

@app.route('/api/change-password', methods=['POST'])
@require_auth
def change_password():
    """Change current user's password."""
    data = request.get_json()
    if not data or 'old_password' not in data or 'new_password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    username = request.current_user
    user = user_store.get(username)
    if not user:
        abort(404)

    if not verify_password(data['old_password'], user['password_hash']):
        return jsonify({'error': 'Current password incorrect'}), 401

    if len(data['new_password']) < 12:
        return jsonify({'error': 'Password must be at least 12 characters'}), 400

    user['password_hash'] = hash_password(data['new_password'])
    log_action('password_change', username)
    return jsonify({'message': 'Password changed successfully'})

if __name__ == '__main__':
    # Create default admin
    admin_pass = os.environ.get('ADMIN_PASSWORD')
